 34	import Geometry.Registration.CoherentPointDrift;
 35	
 36	namespace
 37	{
 38	    namespace CPD = Geometry::CoherentPointDrift;
 39	    namespace E = CPD::EStep;
 40	
 41	    struct Fixture
 42	    {
 43	        std::vector<glm::vec3> Source, Target, Truth; // Truth[i]: image of Source[i]
 44	        std::vector<bool> Clutter;                     // per target point
 45	    };
 46	
 47	    Fixture Make(const std::string& kind, const std::size_t count, const std::uint32_t seed)
 48	    {
 49	        Fixture f;
 50	        f.Source = CpdScaling::Surface(count, seed);
 51	        const glm::dmat3 rotation(glm::rotate(glm::dmat4(1.0), 0.3, glm::normalize(glm::dvec3(1.0, 2.0, 0.5))));
 52	        const double scale = 1.1;
 53	        const glm::dvec3 translation{0.3, -0.2, 0.1};
 54	        std::mt19937 random(seed ^ 0x9e3779b9u);
 55	        std::normal_distribution<double> noise(0.0, 0.004);
 56	        std::uniform_real_distribution<double> clutter(-1.6, 1.6);
 57	        for (std::size_t i = 0; i < count; ++i)
 58	        {
 59	            const glm::dvec3 p(f.Source[i]);
 60	            const glm::dvec3 bent = p + glm::dvec3(0.0, 0.12 * std::sin(1.8 * p.x), 0.1 * std::cos(1.4 * p.y));
 61	            const glm::dvec3 q = scale * (rotation * bent) + translation;
 62	            f.Truth.push_back(glm::vec3(q));
 63	            const bool isClutter = i % 20 == 0;
 64	            const glm::dvec3 x = isClutter ? glm::dvec3(clutter(random), clutter(random), clutter(random))
 65	                                           : q + glm::dvec3(noise(random), noise(random), noise(random));
 66	            if (kind == "partial" && !isClutter && q.x >= 0.2) continue;
 67	            f.Target.push_back(glm::vec3(x));
 68	            f.Clutter.push_back(isClutter);
 69	        }
 70	        return f;
 71	    }
 72	
 73	    // A reference of exactly `count` double3 positions (any other size is refused).
 74	    std::optional<std::vector<glm::dvec3>> ReadPositions(const std::string& path, const std::size_t count)
 75	    {
 76	        std::ifstream in(path, std::ios::binary | std::ios::ate);
 77	        if (!in || std::size_t(in.tellg()) != count * sizeof(glm::dvec3)) return std::nullopt;
 78	        in.seekg(0);
 79	        std::vector<glm::dvec3> out(count);
 80	        if (!in.read(reinterpret_cast<char*>(out.data()), std::streamsize(count * sizeof(glm::dvec3)))) return std::nullopt;
 81	        return out;
 82	    }
